   177|
   178|export const ROLE_AGENT_IDS = Object.keys(ROLE_AGENTS) as RoleAgentId[];
   179|
   180|// ── State types ──────────────────────────────────────────────────────────────
   181|
   182|export type RoleQueueItem = {
   183|  id: string;
   184|  goal: string;
   185|  /** Owner-flagged destructive task — requires an approver to execute. */
   186|  destructive: boolean;
   187|  approverEmail: string | null;
   188|  enqueuedAt: string;
   189|};
   190|
   191|export type RoleRunStatus = 'completed' | 'failed' | 'blocked';
   192|
   193|export type RoleOutputRecord = {
   194|  id: string;
   195|  agentId: RoleAgentId;
   196|  at: string;
   197|  goal: string;
   198|  status: RoleRunStatus;
   199|  risk: AgentRiskLevel;
   200|  /** Framework task id this run produced (for cross-referencing the audit log). */
   201|  frameworkTaskId: string | null;
   202|  /** Owner-gated destructive work that was blocked pending approval. */
   203|  ownerGated: boolean;
   204|  approvedBy: string | null;
   205|  /** The real, grounded output the agent produced this run. */
   206|  output: string;
   207|  durationMs: number;
   208|};
   209|
   210|export type RoleAgentState = {
   211|  id: RoleAgentId;
   212|  queue: RoleQueueItem[];
   213|  lastRunAt: string | null;
   214|  nextRunAt: string | null;
   215|  runCount: number;
   216|  successCount: number;
   217|  failureCount: number;
   218|  ownerGatedCount: number;
   219|  outputs: RoleOutputRecord[];
   220|};
   221|
   222|export type RoleAgentsState = {
   223|  marker: string;
   224|  startedAt: string;
   225|  updatedAt: string;
   226|  enabled: boolean;
   227|  agents: Record<RoleAgentId, RoleAgentState>;
   228|};
   229|
   230|const MAX_OUTPUTS = 50;
   231|const MAX_QUEUE = 100;
   232|
   233|const DIR = path.join(process.cwd(), 'logs', 'audit', 'role-agents');
   234|const STATE_PATH = path.join(DIR, 'state.json');
   235|const TMP_PATH = path.join(DIR, 'state.json.tmp');
   236|const LOG_PATH = path.join(DIR, 'runs.jsonl');
   237|
   238|function nowIso(now: number = Date.now()): string {
   239|  return new Date(now).toISOString();
   240|}
   241|
   242|function uid(prefix: string): string {
   243|  if (typeof crypto !== 'undefined' && typeof crypto.randomUUID === 'function') {
   244|    return `${prefix}_${crypto.randomUUID()}`;
   245|  }
   246|  return `${prefix}_${Date.now().toString(36)}_${Math.random().toString(36).slice(2, 8)}`;
   247|}
   248|
   249|// ── Fresh state ──────────────────────────────────────────────────────────────
   250|
   251|export function freshRoleAgentState(id: RoleAgentId): RoleAgentState {
   252|  return {
   253|    id,
   254|    queue: [],
   255|    lastRunAt: null,
   256|    nextRunAt: nowIso(),
   257|    runCount: 0,
   258|    successCount: 0,
   259|    failureCount: 0,
   260|    ownerGatedCount: 0,
   261|    outputs: [],
   262|  };
   263|}
   264|
   265|export function freshRoleAgentsState(now: number = Date.now()): RoleAgentsState {
   266|  const agents = {} as Record<RoleAgentId, RoleAgentState>;
   267|  for (const id of ROLE_AGENT_IDS) agents[id] = freshRoleAgentState(id);
   268|  return {
   269|    marker: ROLE_AGENTS_MARKER,
   270|    startedAt: nowIso(now),
   271|    updatedAt: nowIso(now),
   272|    enabled: true,
   273|    agents,
   274|  };
   275|}
   276|
   277|function normalizeState(parsed: unknown): RoleAgentsState {
   278|  const fresh = freshRoleAgentsState();
   279|  if (!parsed || typeof parsed !== 'object') return fresh;
   280|  const obj = parsed as Partial<RoleAgentsState>;
   281|  const incoming = (obj.agents ?? {}) as Partial<Record<RoleAgentId, RoleAgentState>>;
   282|  const agents = {} as Record<RoleAgentId, RoleAgentState>;
   283|  for (const id of ROLE_AGENT_IDS) {
   284|    const a = incoming[id];
   285|    agents[id] = {
   286|      ...fresh.agents[id],
   287|      ...(a ?? {}),
   288|      id,
   289|      queue: Array.isArray(a?.queue) ? a!.queue.slice(0, MAX_QUEUE) : [],
   290|      outputs: Array.isArray(a?.outputs) ? a!.outputs.slice(0, MAX_OUTPUTS) : [],
   291|    };
   292|  }
   293|  return {
   294|    marker: ROLE_AGENTS_MARKER,
   295|    startedAt: typeof obj.startedAt === 'string' ? obj.startedAt : fresh.startedAt,
   296|    updatedAt: typeof obj.updatedAt === 'string' ? obj.updatedAt : fresh.updatedAt,
   297|    enabled: typeof obj.enabled === 'boolean' ? obj.enabled : true,
   298|    agents,
   299|  };
   300|}
   301|
   302|// ── Durable I/O (Supabase when configured, filesystem otherwise) ─────────────
   303|
   304|let writeChain: Promise<void> = Promise.resolve();
   305|
   306|function enqueueWrite<T>(task: () => Promise<T>): Promise<T> {
   307|  const run = writeChain.then(task, task);
   308|  writeChain = run.then(() => undefined, () => undefined);
   309|  return run;
   310|}
   311|
   312|export async function getRoleAgentsState(): Promise<RoleAgentsState> {
   313|  if (isDurableStoreConfigured()) {
   314|    try {
   315|      const parsed = await readDurableJson<unknown>(STATE_PATH, null);
   316|      return parsed ? normalizeState(parsed) : freshRoleAgentsState();
   317|    } catch {
   318|      return freshRoleAgentsState();
   319|    }
   320|  }
   321|  try {
   322|    const raw = await readFile(STATE_PATH, 'utf8');
   323|    return normalizeState(JSON.parse(raw));
   324|  } catch {
   325|    return freshRoleAgentsState();
   326|  }
   327|}
   328|
   329|async function writeRoleAgentsState(state: RoleAgentsState): Promise<void> {
   330|  const next: RoleAgentsState = { ...state, updatedAt: nowIso() };
   331|  if (isDurableStoreConfigured()) {
   332|    await writeDurableJson(STATE_PATH, next);
   333|    return;
   334|  }
   335|  // Atomic write: temp file lives in the same directory so the final rename
   336|  // is always on the same filesystem (no EXDEV). Parallel test directory
   337|  // deletion is handled by recreating the directory and retrying.
   338|  const tmp = path.join(DIR, `state.json.tmp-${randomUUID()}`);
   339|  for (let attempt = 1; attempt <= 3; attempt += 1) {
   340|    await mkdir(DIR, { recursive: true });
   341|    await writeFile(tmp, JSON.stringify(next, null, 2), 'utf8');
   342|    try {
   343|      await rename(tmp, STATE_PATH);
   344|      return;
   345|    } catch (error) {
   346|      const code = (error as { code?: string }).code;
   347|      if (code === 'ENOENT' && attempt < 3) {
   348|        continue;
   349|      }
   350|      throw error;
   351|    }
   352|  }
   353|}
   354|
   355|async function appendRunLog(event: Record<string, unknown>): Promise<void> {
   356|  try {
   357|    if (isDurableStoreConfigured()) {
   358|      await appendDurableEvent(LOG_PATH, event);
   359|      return;
   360|    }
   361|    await mkdir(DIR, { recursive: true });
   362|    await appendFile(LOG_PATH, `${JSON.stringify({ ...event, at: event.at ?? nowIso() })}\n`, 'utf8');
   363|  } catch {
   364|    // forensic log is best-effort.
   365|  }
   366|}
   367|
   368|async function mutateAgent(
   369|  id: RoleAgentId,
   370|  mutator: (agent: RoleAgentState, state: RoleAgentsState) => void,
   371|): Promise<RoleAgentState> {
   372|  return enqueueWrite(async () => {
   373|    const state = await getRoleAgentsState();
   374|    mutator(state.agents[id], state);
   375|    await writeRoleAgentsState(state);
   376|    return state.agents[id];
   377|  });
   378|}
   379|
   380|// ── Queue ────────────────────────────────────────────────────────────────────
   381|
   382|/** Detect destructive intent from a goal against the agent's destructive list. */
   383|export function isDestructiveGoal(id: RoleAgentId, goal: string): boolean {
   384|  const lower = goal.toLowerCase();
   385|  const def = ROLE_AGENTS[id];
   386|  if (def.destructiveActions.some((a) => lower.includes(a.toLowerCase()))) return true;
   387|  // Reuse the framework's high-risk classifier as a second safety net.
   388|  return classifyTaskRisk(goal) === 'high';
   389|}
   390|
   391|export async function enqueueRoleTask(input: {
   392|  agentId: RoleAgentId;
   393|  goal: string;
   394|  destructive?: boolean;
   395|  approverEmail?: string | null;
   396|}): Promise<RoleQueueItem> {
   397|  const goal = input.goal.trim();
   398|  if (!goal) throw new Error('goal is required.');
   399|  const item: RoleQueueItem = {
   400|    id: uid('rq'),
   401|    goal,
   402|    destructive: input.destructive ?? isDestructiveGoal(input.agentId, goal),
   403|    approverEmail: input.approverEmail?.trim() || null,
   404|    enqueuedAt: nowIso(),
   405|  };
   406|  await mutateAgent(input.agentId, (agent) => {
   407|    agent.queue.push(item);
   408|    if (agent.queue.length > MAX_QUEUE) agent.queue.splice(0, agent.queue.length - MAX_QUEUE);
   409|  });
   410|  await appendRunLog({ type: 'enqueue', agentId: input.agentId, goal, destructive: item.destructive });
   411|  return item;
   412|}
   413|
   414|// ── Run loop ─────────────────────────────────────────────────────────────────
   415|
   416|/** Per-process guard so one agent never runs twice concurrently. */
   417|const inFlight = new Set<RoleAgentId>();
   418|
   419|/**
   420| * Produce a grounded output line for an executed heartbeat/queue task. This is
   421| * deterministic and read-only — it never invents external facts; it reports what
   422| * the agent evaluated and which framework lane handled it.
   423| */
   424|function buildOutput(def: RoleAgentDefinition, goal: string, risk: AgentRiskLevel, frameworkTaskId: string): string {
   425|  const fw = AGENTS[def.frameworkAgent];
   426|  return `${def.roleName} executed "${goal}" via ${fw.name} lane (risk=${risk}, task=${frameworkTaskId}). Allowed tools: ${def.allowedTools.join(', ')}. Output persisted to ${def.memoryNamespace}.`;
   427|}
   428|
   429|/**
   430| * Run ONE cycle for a single role agent. Pops the next queued task (or runs the
   431| * heartbeat goal), classifies risk, and routes through the existing framework
   432| * risk gate. Owner-gated destructive work without an approver is recorded as
   433| * `blocked` and NEVER executed. Never throws.
   434| */
   435|export async function runRoleAgent(id: RoleAgentId): Promise<RoleOutputRecord> {
   436|  const def = ROLE_AGENTS[id];
   437|  const start = Date.now();
   438|
   439|  if (inFlight.has(id)) {
   440|    return {
   441|      id: uid('out'),
   442|      agentId: id,
   443|      at: nowIso(),
   444|      goal: def.heartbeatGoal,
   445|      status: 'blocked',
   446|      risk: 'low',
   447|      frameworkTaskId: null,
   448|      ownerGated: false,
   449|      approvedBy: null,
   450|      output: `${def.roleName} skipped: a run is already in flight.`,
   451|      durationMs: 0,
   452|    };
   453|  }
   454|  inFlight.add(id);
   455|
   456|  try {
   457|    // Pop the next queued task atomically; fall back to the heartbeat goal.
   458|    // NOTE: use an object holder so TS control-flow analysis does not narrow the
   459|    // closure-mutated value to `never` (it cannot track assignments inside the
   460|    // mutateAgent callback).
   461|    const holder: { item: RoleQueueItem | null } = { item: null };
   462|    await mutateAgent(id, (agent) => {
   463|      holder.item = agent.queue.shift() ?? null;
   464|    });
   465|    const queued: RoleQueueItem | null = holder.item;
   466|    const goal = queued?.goal ?? def.heartbeatGoal;
   467|    const destructive = queued?.destructive ?? isDestructiveGoal(id, goal);
   468|    const approverEmail = queued?.approverEmail ?? null;
   469|    const risk = classifyTaskRisk(goal);
   470|
   471|    let record: RoleOutputRecord;
   472|
   473|    if (destructive && !approverEmail) {
   474|      // Owner-gated: never execute destructive work without an explicit approver.
   475|      record = {
   476|        id: uid('out'),
   477|        agentId: id,
   478|        at: nowIso(),
   479|        goal,
   480|        status: 'blocked',
   481|        risk,
   482|        frameworkTaskId: null,
   483|        ownerGated: true,
   484|        approvedBy: null,
   485|        output: `${def.roleName} BLOCKED "${goal}" — owner-gated destructive action requires an explicit approver. No change made.`,
   486|        durationMs: Date.now() - start,
   487|      };
   488|    } else {
   489|      // Route through the existing framework (risk gate + audit + lifecycle).
   490|      const dispatch = dispatchTask({
   491|        goal,
   492|        forceAgent: def.frameworkAgent,
   493|        approverEmail: approverEmail ?? undefined,
   494|        metadata: { roleAgent: id, marker: ROLE_AGENTS_MARKER },
   495|      });
   496|      const task = dispatch.task;
   497|
   498|      if (task.status === 'blocked') {
   499|        record = {
   500|          id: uid('out'),
   501|          agentId: id,
   502|          at: nowIso(),
   503|          goal,
   504|          status: 'blocked',
   505|          risk,
   506|          frameworkTaskId: task.id,
   507|          ownerGated: true,
   508|          approvedBy: task.approvedBy,
   509|          output: `${def.roleName} BLOCKED by risk gate: ${task.blockedReason ?? 'owner approval required.'}`,
   510|          durationMs: Date.now() - start,
   511|        };
   512|      } else {
   513|        const output = buildOutput(def, goal, risk, task.id);
   514|        completeTask(task.id, { roleAgent: id, output, marker: ROLE_AGENTS_MARKER });
   515|        writeAgentMemory(def.frameworkAgent, `role:${id}:last_output`, output, { roleAgent: id });
   516|        record = {
   517|          id: uid('out'),
   518|          agentId: id,
   519|          at: nowIso(),
   520|          goal,
   521|          status: 'completed',
   522|          risk,
   523|          frameworkTaskId: task.id,
   524|          ownerGated: false,
   525|          approvedBy: task.approvedBy,
   526|          output,
   527|          durationMs: Date.now() - start,
   528|        };
   529|      }
   530|    }
   531|
   532|    // Persist run result + stats.
   533|    await mutateAgent(id, (agent) => {
   534|      agent.lastRunAt = record.at;
   535|      agent.nextRunAt = nowIso(Date.now() + def.intervalMs);
   536|      agent.runCount += 1;
   537|      if (record.status === 'completed') agent.successCount += 1;
   538|      else if (record.status === 'failed') agent.failureCount += 1;
   539|      if (record.ownerGated) agent.ownerGatedCount += 1;
   540|      agent.outputs.unshift(record);
   541|      if (agent.outputs.length > MAX_OUTPUTS) agent.outputs.length = MAX_OUTPUTS;
   542|    });
   543|    await appendRunLog({ type: 'run', agentId: id, status: record.status, goal, taskId: record.frameworkTaskId });
   544|    return record;
   545|  } catch (error) {
   546|    const record: RoleOutputRecord = {
   547|      id: uid('out'),
   548|      agentId: id,
   549|      at: nowIso(),
   550|      goal: def.heartbeatGoal,
